/// Names a rendered effect from its precompute's clip name.
///
/// Observed names include `<sequence>,<Effect>+<N>` and
/// `<sequence>,<Effect>,<N>[.new.<N>...]`. Exact known display spellings use
/// spaces/colons as underscores; sequence names can contain commas.
/// This lookup labels rows already classified as precomputes by metadata.
/// A clip name is editable, so a match is a label, not proof of effect identity.
///
/// Names/categories come from the installed Media Composer 26.8.0.58987 ARM64
/// registrations and shipped resources. Distinct AlphaFlex variants and
/// ambiguous categories are retained. See docs/avid-effects-catalogue.md.
namespace AvidEffects
{
	struct Hit
	{
		QString name;	  ///< Avid's display name ("Color Correction"), or the raw token when unknown.
		QString category; ///< Avid category/group ("Image", "Timewarp"...), "A / B" when ambiguous,
						  ///< "unknown" when unknown (a user-typed title,
						  ///< an unregistered plug-in, or a renamed template).
		QString sequence; ///< The text preceding the effect token, as Avid wrote it (mangled).
		int instance = 0; ///< The +N or comma-N instance; 0 when absent or invalid.
		bool matched = false;
	};

	/// Parse a precompute clip name and look the effect up. An unrecognised
	/// effect token is returned verbatim, unmatched. Malformed or out-of-range
	/// numeric suffixes remain in the token rather than being silently lost.
	[[nodiscard]] Hit lookup(const QString &clipName);

struct Table
{
	QVector<Row> rows;
	QHash<QString, QVector<int>> byKey; ///< mangled name (any language) → rows
};

/// Build the name index once from the compiled-in catalogue.
const Table &table()
{
	static const Table t = []
	{
		Table out;
		out.rows.reserve(std::size(kEffects));
		for (const Entry &e : kEffects)
		{
			const int idx = out.rows.size();
			out.rows.append({QString::fromUtf8(e.name), QString::fromUtf8(e.category)});
			// English name, then every localised spelling Avid ships.
			QSet<QString> keys{AvidEffects::mangle(out.rows[idx].name)};
			for (const char *localised : e.localised)
				if (localised && *localised)
					keys.insert(AvidEffects::mangle(QString::fromUtf8(localised)));
			for (const QString &k : keys)
				out.byKey[k].append(idx);
		}
		// Observed render spelling, corroborated by the current 3D Warp
		// registration and 2026 Effects Guide. This explicit compatibility
		// alias does not identify the producer's AlphaFlex execution variant.
		out.byKey.insert(QStringLiteral("3DWarp"),
						 out.byKey.value(QStringLiteral("3D_Warp")));
		return out;
	}();
	return t;
}

AvidEffects::Hit AvidEffects::lookup(const QString &clipName)
{
	// Effect names and categories come only from the clip name, not an effect ID.
	// If a rename removes the effect name, this lookup cannot recover it:
	// unmatched text is kept with category "unknown". A name that
	// happens to match another effect can also give a misleading label.
	// This does not change the media type established separately from metadata.
	Hit hit;
	// Both observed render names keep the effect at the right-hand end:
	// `<sequence>,<Effect>+<N>` and `<sequence>,<Effect>,<N>[.new.<N>...]`.
	// Validate the latter's entire numeric suffix before using the preceding
	// comma; earlier commas still belong to the sequence.
	QString token = clipName;
	const int comma = clipName.lastIndexOf(QLatin1Char(','));
	if (comma >= 0)
	{
		hit.sequence = clipName.left(comma);
		token = clipName.mid(comma + 1);
	}
	bool commaInstance = false;
	static const QRegularExpression kCommaInstance(QStringLiteral("\\A[0-9]+(?:\\.new\\.[0-9]+)*\\z"));
	if (comma > 0 && kCommaInstance.match(token).hasMatch())
	{
		const int effectComma = clipName.lastIndexOf(QLatin1Char(','), comma - 1);
		if (effectComma >= 0 && effectComma + 1 < comma)
		{
			const QStringList numbers = token.split(QStringLiteral(".new."));
			bool valid = true;
			int instance = 0;
			for (qsizetype i = 0; i < numbers.size(); ++i)
			{
				bool ok = false;
				const int value = numbers[i].toInt(&ok);
				if (!ok)
				{
					valid = false;
					break;
				}
				if (i == 0)
					instance = value;
			}
			if (valid)
			{
				hit.sequence = clipName.left(effectComma);
				token = clipName.mid(effectComma + 1, comma - effectComma - 1);
				hit.instance = instance;
				commaInstance = true;
			}
		}
	}
	if (!commaInstance)
	{
		static const QRegularExpression kInstance(QStringLiteral("\\+([0-9]+)\\z"));
		const QRegularExpressionMatch m = kInstance.match(token);
		if (m.hasMatch() && m.capturedStart(0) > 0)
		{
			bool ok = false;
			const int instance = m.captured(1).toInt(&ok);
			if (ok)
			{
				hit.instance = instance;
				token.chop(m.capturedLength(0));
			}
		}
	}

	const Table &t = table();
	const auto it = t.byKey.constFind(token);
	if (it == t.byKey.constEnd() || it->isEmpty())
	{
		hit.name = token;
		hit.category = QStringLiteral("unknown");
		return hit;
	}
	hit.matched = true;
	hit.name = t.rows[it->first()].name;
	// One name can live in several palette groups ("Bottom to Top" is a
	// Conceal, a Peel, a Push and a Squeeze); say all of them, in file order.
	QStringList categories;
	for (int idx : *it)
		if (!categories.contains(t.rows[idx].category))
			categories << t.rows[idx].category;
	hit.category = categories.join(QStringLiteral(" / "));
	return hit;
}

void selectEffectMetadata(MediaEvidence &evidence)
{
	const auto fields = {MediaProperty::Effect, MediaProperty::EffectCategory, MediaProperty::EffectSequence};
	const QString locator = QStringLiteral("MediaEngine.EffectFromClipName");
	for (const auto field : fields)
		evidence.excludeInterpretation(field, locator);
	const auto name = evidence.selected(MediaProperty::ClipName);
	const auto type = evidence.selected(MediaProperty::Type);
	const auto &names = evidence.observations(MediaProperty::ClipName);
	if (type.value.isValid() && type.value.toInt() == int(MediaType::Precompute) &&
		name.selectedObservation >= 0 && name.selectedObservation < names.size())
	{
		const auto hit = AvidEffects::lookup(name.value.toString());
		for (const auto field : fields)
		{
			auto item = names[name.selectedObservation];
			item.property = locator;
			item.value = field == MediaProperty::Effect ? hit.name : field == MediaProperty::EffectCategory ? hit.category
																											: hit.sequence;
			item.basis = EvidenceBasis::Derived;
			item.explanation = QStringLiteral("Inferred from the selected precompute clip name using the Avid effect-name catalogue; editable names do not prove effect identity. Source property: %1").arg(names[name.selectedObservation].property);
			evidence.observe(field, std::move(item));
		}
	}
	for (const auto field : fields)
		evidence.select(field, resolveProperty(evidence, propertyPolicy(field)));

QString effectDisplay() const
{
	if (type != Type::Precompute)
		return {};
	return effect.isEmpty() ? QStringLiteral("unknown") : effect;
}

QString effectCategoryDisplay() const
{
	if (type != Type::Precompute)
		return {};
	return effectCategory.isEmpty() ? QStringLiteral("unknown") : effectCategory;
}

